INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('0VYv5WqQkkCkhN2LxaH8', 'yhC9xTlB6yPlERoUgg2dh2WNsxq1', 'Carlos Pérez Dávila', 'visionario2306@gmail.com', 'papa', 'Papa', true, NULL, '"Temperatura: 28.9°C | Lluvia hoy: 0.1mm | pH suelo: 7.8 (Ligeramente alcalino)"'::jsonb, '{"tiene_problema":false,"nombre_problema":"No se observa cultivo de papa","nombre_cientifico":"","gravedad":"ninguna","que_tiene":"Las imágenes muestran un campo de caña de azúcar y un agricultor, pero no se visualiza ningún cultivo de papa para evaluar su estado fitosanitario.","productos":[]}'::jsonb, NULL, '2026-08-12T21:08:43.834Z', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('327eT8b781AeJJArIO4g', NULL, NULL, NULL, 'papa', 'Papa', true, NULL, NULL, '{"tiene_problema":true,"nombre_problema":"Deficiencia de Nitrógeno","nombre_cientifico":"N/A","gravedad":"moderada","que_tiene":"¡Uy, tus papitas están amarillas! Las hojas más viejas se ven pálidas, de un amarillo verdoso a amarillo intenso. Las venas de las hojas también se ven amarillas. Esto es un signo claro de que a tu planta le falta un nutriente muy importante para crecer fuerte y verde.","productos":[{"nombre":"Urea Agrícola","ingrediente_activo":"Nitrógeno (46%)","dosis":"100-150 kg/ha, fraccionado en 2-3 aplicaciones","frecuencia":"Cada 15-20 días, según el estado de la planta y análisis de suelo","carencia":"N/A"},{"nombre":"Nitrato de Amonio","ingrediente_activo":"Nitrógeno (33.5%)","dosis":"80-120 kg/ha, fraccionado","frecuencia":"Cada 15-20 días","carencia":"N/A"},{"nombre":"Fertilizante Foliar con Nitrógeno (ej. Folicare)","ingrediente_activo":"Nitrógeno (varios porcentajes)","dosis":"2-3 kg/200 L de agua","frecuencia":"Cada 7-10 días, hasta que las hojas recuperen su color","carencia":"N/A"}]}'::jsonb, NULL, '2026-08-08T03:29:48.587Z', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('35tlQjL7zgjz57gnNip6', 'anonimo', 'Agricultor', NULL, 'Cacao', NULL, false, NULL, NULL, '{"tiene_problema":true,"nombre_problema":"Mancha Negra","gravedad":"moderada","que_tiene":"El cacao presenta manchas oscuras en los frutos, lo que puede ser un signo de enfermedad fúngica.","que_hacer":"Retirar las frutas afectadas para evitar la propagación. Mejorar la ventilación del cultivo.","productos":[{"nombre":"Fungicida de cobre","dosis":"Aplicar según las instrucciones del fabricante, generalmente cada 15 días."}],"prevencion":"Mantener el área libre de hojas y frutos caídos, y podar regularmente para mejorar la circulación de aire."}'::jsonb, NULL, '2026-04-16T06:24:36.010Z', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('3TvsRAWqKpa2XYrnr94i', 'yhC9xTlB6yPlERoUgg2dh2WNsxq1', 'Carlos Pérez Dávila', 'visionario2306@gmail.com', 'cana', 'Caña de azúcar', true, NULL, '"Temperatura: 22.4°C | Lluvia hoy: 0mm | pH suelo: 7.5 (Ligeramente alcalino)"'::jsonb, '{"tiene_problema":true,"nombre_problema":"Roya","nombre_cientifico":"Puccinia melanocephala","gravedad":"moderada","que_tiene":"Lesiones alargadas de color rojizo a marrón en hojas y tallos","productos":[{"nombre":"Amistar","ingrediente_activo":"Azoxistrobina","dosis":"1 L/ha","frecuencia":"cada 15 días","carencia":"30 días"}]}'::jsonb, NULL, '2026-06-10T13:13:58.227Z', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('3sODjfGqPHR5To7k6Lro', 'user_1774866471708', 'Mercedes Dávila', NULL, 'Maíz', NULL, false, NULL, NULL, '{"tiene_problema":true,"nombre_problema":"Crecimiento desigual y posible estrés hídrico","gravedad":"moderada","que_tiene":"El maíz muestra un crecimiento desigual y algunas plantas parecen estar amarillentas, lo que puede indicar falta de agua o nutrientes.","que_hacer":"Asegúrate de que el riego sea adecuado y uniforme. Revisa el suelo para ver si hay compactación que impida la absorción de agua y nutrientes.","productos":[{"nombre":"Fertilizante balanceado","dosis":"Aplicar 50 kg por hectárea"}],"prevencion":"Mantén un programa regular de riego y fertilización. Monitorea las plantas regularmente para detectar problemas temprano."}'::jsonb, NULL, '2026-04-03T20:47:36.776Z', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('4TIPB6UC5iboWNTDhWPa', 'BvMsG5HlkK2cGuqjvlDS', 'jose edin llanos davila', NULL, 'Papa', NULL, false, NULL, NULL, '{"tiene_problema":true,"nombre_problema":"Deficiencia de nutrientes","gravedad":"moderada","que_tiene":"Las hojas amarillas indican una posible deficiencia de nitrógeno.","que_hacer":"Aplicar fertilizante rico en nitrógeno.","productos":[{"nombre":"Urea","dosis":"50 kg por hectárea"},{"nombre":"Nitrato de amonio","dosis":"100 kg por hectárea"}],"prevencion":"Mantener un programa de fertilización balanceado y monitorear regularmente los niveles de nutrientes."}'::jsonb, NULL, '2026-03-22T21:25:05.310Z', 8) ON CONFLICT (id) DO NOTHING;
