INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('BVaxrKOAagh8e68GEoct', 'GsCQ2RXNkzLOWPxNLQKNxDWBVYy2', 'José Edin llanos Dávila', 'joseedinllanos@gmail.com', 'maiz', 'Maíz', true, NULL, '"Temperatura: 12.9°C | Lluvia hoy: 5.1mm | pH suelo: 6.0 (Ligeramente ácido)"'::jsonb, '{"tiene_problema":true,"nombre_problema":"Gusano Cogollero","nombre_cientifico":"Spodoptera frugiperda","gravedad":"moderada","que_tiene":"¡Ay, caramba! Tu maíz tiene unas perforaciones y raspaduras en las hojas, especialmente en las más nuevas y en el cogollo. ¡Eso es señal del famoso Gusano Cogollero! También se ven excrementos (como aserrín) en el cogollo.","productos":[{"nombre":"Coragen","ingrediente_activo":"Clorantraniliprol","dosis":"100 - 150 ml por hectárea (o 10-15 ml por mochila de 20L)","frecuencia":"Una aplicación, si es necesario repetir a los 7-10 días.","carencia":"1 día"},{"nombre":"Ampligo","ingrediente_activo":"Clorantraniliprol + Lambda-cihalotrina","dosis":"200 ml por hectárea (o 20 ml por mochila de 20L)","frecuencia":"Una aplicación, si es necesario repetir a los 7-10 días.","carencia":"7 días"}]}'::jsonb, NULL, '2026-08-08T15:56:35.054Z', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('BWGfcGnKlEhLCQrz2WyC', '9GdcjYjtvaW2YjiE6bdvwvRxmJV2', 'José Edin Llanos Dávila', 'jose.llanos.d@uni.pe', 'papa', 'Papa', true, NULL, NULL, '{"que_tiene":"Manchas acuosas oscuras en hojas, con borde amarillo y moho blanco en envés. Causas: alta humedad (lluvias) y temperaturas entre 10-20°C.","gravedad":"moderada","productos":[{"frecuencia":"Cada 7-10 días, máximo 3 aplicaciones","nombre":"Ridomil Gold MZ 68 WG","dosis":"2.5 kg/ha en 200 L de agua","carencia":"14 días","ingrediente_activo":"Metalaxil-M + Mancozeb"},{"frecuencia":"Cada 7 días","nombre":"Curzate M8","dosis":"2 kg/ha en 200 L de agua","carencia":"7 días","ingrediente_activo":"Cimoxanil + Mancozeb"}],"nombre_problema":"Tizón tardío","tiene_problema":true,"nombre_cientifico":"Phytophthora infestans"}'::jsonb, NULL, '2026-07-23T07:08:55.831Z', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('CKYCoGSxRFmDR5vysIWu', NULL, NULL, NULL, 'papa', 'Papa', true, NULL, NULL, '{"tiene_problema":true,"nombre_problema":"Deficiencia de Nitrógeno","nombre_cientifico":"N/A","gravedad":"moderada","que_tiene":"¡Uy, tus papas están pidiendo auxilio! Se ve un amarillamiento generalizado en las hojas más viejas, empezando por las puntas y los bordes. Las venas de las hojas también se ven amarillas, no solo el tejido entre ellas. Esto es un claro signo de que a tu planta le falta un nutriente muy importante.","productos":[{"nombre":"Urea Agrícola","ingrediente_activo":"Nitrógeno (N) 46%","dosis":"100-150 kg/ha, fraccionado en 2-3 aplicaciones durante el ciclo de cultivo. Para esta etapa, 50 kg/ha.","frecuencia":"Una aplicación ahora y otra a los 15-20 días si es necesario.","carencia":"N/A"},{"nombre":"Nitrofoska Especial","ingrediente_activo":"N-P-K (12-12-17) + micronutrientes","dosis":"200-300 kg/ha, aplicado al momento de la siembra o en la primera aporcada. Para esta etapa, 100 kg/ha como complemento.","frecuencia":"Una aplicación ahora.","carencia":"N/A"},{"nombre":"Foliar N (ej. Fetrilon Combi)","ingrediente_activo":"Nitrógeno (N) + micronutrientes","dosis":"2-3 kg/ha disuelto en 200 litros de agua.","frecuencia":"Cada 7-10 días hasta que las hojas recuperen su color.","carencia":"N/A"}]}'::jsonb, NULL, '2026-08-08T03:30:39.070Z', 8) ON CONFLICT (id) DO NOTHING;
