INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('IVrDHDBEeYvCA3DwCkdH', 'yhC9xTlB6yPlERoUgg2dh2WNsxq1', 'Carlos Pérez Dávila', 'visionario2306@gmail.com', 'cana', 'Caña de azúcar', true, NULL, NULL, '{"gravedad":"moderada","tiene_problema":true,"nombre_cientifico":"Varias especies de gramíneas y dicotiledóneas","que_tiene":"Detección: Se observa una gran cantidad de malezas de diferentes tipos (gramíneas y algunas de hoja ancha) creciendo vigorosamente entre las hileras de caña de azúcar. Estas malezas compiten por luz, agua y nutrientes con el cultivo principal. Causas probables: Falta de control temprano de malezas, condiciones favorables para su crecimiento (humedad, luz). Prevención: Preparación adecuada del terreno, uso de variedades de caña de rápido crecimiento, rotación de cultivos, limpieza de maquinaria.","productos":[{"nombre":"Gesapax Combi","frecuencia":"Una aplicación post-emergencia temprana de la caña y malezas.","ingrediente_activo":"Ametrina + Atrazina","carencia":"No aplica (aplicación temprana)","dosis":"3.0 - 4.0 kg/ha"},{"carencia":"No aplica (aplicación temprana)","dosis":"1.5 - 2.5 kg/ha","nombre":"Diuron 80 WG","ingrediente_activo":"Diuron","frecuencia":"Una aplicación post-emergencia temprana, preferiblemente con suelo húmedo."}],"nombre_problema":"Malezas de hoja angosta y ancha"}'::jsonb, NULL, '2026-07-27T21:23:11.351Z', 7) ON CONFLICT (id) DO NOTHING;
