INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('TgyCjCZLUnfn7fvawfM9', 'c7foiY2YUSQQIQDiQ6eSsuJSXgF2', 'José Edin llanos Dávila ', 'joseedinllanos@gmail.com', 'papa', 'Papa', true, NULL, '"Temperatura: 12°C | Lluvia hoy: 5.9mm | pH suelo: 6.1 (Ligeramente ácido)"'::jsonb, '{"gravedad":"moderada","nombre_problema":"Ataque de gusano cogollero","productos":[{"dosis":"100 ml por 200 litros de agua","ingrediente_activo":"Clorantraniliprol","nombre":"Coragen","frecuencia":"Una aplicación, repetir si es necesario a los 7-10 días, dependiendo del nivel de infestación.","carencia":"1 día"},{"carencia":"7 días","dosis":"200 ml por 200 litros de agua","ingrediente_activo":"Clorantraniliprol + Lambda-cihalotrina","nombre":"Ampligo","frecuencia":"Una aplicación, repetir si es necesario a los 7-10 días, dependiendo del nivel de infestación."}],"que_tiene":"¡Ay, caramba! Tus papitas están sufriendo un ataque del gusano cogollero. Se ven agujeros grandes y alargados en las hojas, especialmente en las más nuevas y en el cogollo. También se notan raspaduras y excrementos de color verde oscuro. Esto es un claro signo de que este bicho está haciendo de las suyas.","tiene_problema":true,"nombre_cientifico":"Spodoptera frugiperda"}'::jsonb, NULL, '2026-07-27T13:42:10.977Z', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('U0thabRLfSHASDRFJdLM', 'YnzXb2apQAfEz7bsD9Ycsi7svxs2', 'francklyn purizaca vasquez', 'purizacavasquezfrancklyn@gmail.com', 'cana', 'Caña de azúcar', true, 'Que tipo de plaga es', '"Temperatura: 22°C | Lluvia hoy: 0mm | pH suelo: 7.9 (Ligeramente alcalino)"'::jsonb, '{"tiene_problema":true,"nombre_problema":"Broca de la caña","nombre_cientifico":"Diatraea saccharalis","gravedad":"moderada","que_tiene":"Se observa una larva de color verde claro en el cogollo de la caña, así como perforaciones y galerías en las hojas. También se aprecian puntos rojizos en las hojas, que pueden ser síntomas secundarios de estrés o daño por el insecto.","productos":[{"nombre":"Coragen","ingrediente_activo":"Clorantraniliprol","dosis":"100-150 ml/ha","frecuencia":"Según monitoreo, con un máximo de 2 aplicaciones por ciclo de cultivo","carencia":"30 días"},{"nombre":"Ampligo","ingrediente_activo":"Clorantraniliprol + Lambda-cihalotrina","dosis":"200-250 ml/ha","frecuencia":"Según monitoreo, con un máximo de 2 aplicaciones por ciclo de cultivo","carencia":"30 días"}]}'::jsonb, NULL, '2026-07-30T13:14:34.663Z', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('UpJBOJbBwHflYXF8LRF7', NULL, NULL, NULL, 'papa', 'Papa', true, NULL, NULL, '{"tiene_problema":true,"nombre_problema":"Clorosis por deficiencia de nutrientes","nombre_cientifico":"N/A","gravedad":"moderada","que_tiene":"¡Ay, ay, ay! Tus papitas están mostrando un color amarillento en las hojas, especialmente entre las venas, mientras que las venas mismas se mantienen verdes. Esto se llama clorosis y es una señal de que a la planta le falta algo importante para crecer fuerte y sana.","productos":[{"nombre":"Nutri-Papa Mix","ingrediente_activo":"Mezcla de micronutrientes quelatados (Fe, Zn, Mn, B, Cu, Mo)","dosis":"200-300 gramos por cilindro de 200 litros de agua","frecuencia":"Cada 7-10 días, hasta que las hojas recuperen su color verde.","carencia":"No aplica, es un fertilizante foliar."}]}'::jsonb, NULL, '2026-08-08T03:28:55.036Z', 8) ON CONFLICT (id) DO NOTHING;
