INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('oUqu5jkGx06mdlXtihf6', 'YnzXb2apQAfEz7bsD9Ycsi7svxs2', 'francklyn purizaca vasquez', 'purizacavasquezfrancklyn@gmail.com', 'papa', 'Papa', true, 'Que tipo de enfermedad es', '"Temperatura: 22.6°C | Lluvia hoy: 0mm | pH suelo: 7.8 (Ligeramente alcalino)"'::jsonb, '{"tiene_problema":true,"nombre_problema":"Mancha Púrpura","nombre_cientifico":"Alternaria porri","gravedad":"moderada","que_tiene":"¡Ay, mi papita! Veo unas manchas de color púrpura a marrón oscuro, con un borde amarillento, que se están extendiendo por las hojas. Parecen pequeños puntos que se van uniendo. Esto es Mancha Púrpura, un hongo que le gusta el clima húmedo y las temperaturas suaves. Si no lo controlamos, las hojas se secarán y se caerán, afectando el crecimiento de tus papas.","productos":[{"nombre":"Amistar Top","ingrediente_activo":"Azoxystrobin + Difenoconazole","dosis":"0.5 L/ha","frecuencia":"Cada 7-10 días, alternando con otro fungicida.","carencia":"14 días"},{"nombre":"Score","ingrediente_activo":"Difenoconazole","dosis":"0.3 L/ha","frecuencia":"Cada 7-10 días, alternando con otro fungicida.","carencia":"14 días"}]}'::jsonb, NULL, '2026-07-30T13:22:41.224Z', 7) ON CONFLICT (id) DO NOTHING;
