INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('uSbuSXuRkKqaFveZNeS3', '9GdcjYjtvaW2YjiE6bdvwvRxmJV2', 'José Edin Llanos Dávila', 'jose.llanos.d@uni.pe', 'papa', 'Papa', true, NULL, NULL, '{"gravedad":"moderada","que_tiene":"¡Hola, agricultor! Tus plantas de papa están mostrando un color amarillo pálido en las hojas más viejas, especialmente en las de abajo. Esto es un signo claro de que les falta un nutriente muy importante para crecer fuertes y verdes. Las venas de las hojas también se ven más claras.","nombre_cientifico":"N/A","productos":[{"frecuencia":"Según el plan de fertilización, pero para corregir la deficiencia, una aplicación inmediata al suelo y otra a los 15-20 días si es necesario.","dosis":"100-150 kg/ha, fraccionado en 2 aplicaciones (al aporque y al inicio de floración)","nombre":"Urea Agrícola","carencia":"No aplica, es un fertilizante.","ingrediente_activo":"Nitrógeno (46%)"},{"frecuencia":"Una aplicación inmediata y repetir a los 7-10 días si los síntomas persisten.","dosis":"2-3 kg/200 L de agua (mochila de 20 L: 200-300 g)","nombre":"Fertilizante Foliar con Nitrógeno (ej. Folicare 18-18-18 o similar con alto N)","ingrediente_activo":"Nitrógeno, Fósforo, Potasio y micronutrientes","carencia":"No aplica, es un fertilizante."}],"nombre_problema":"Deficiencia de Nitrógeno","tiene_problema":true}'::jsonb, NULL, '2026-07-25T06:19:19.997Z', 7) ON CONFLICT (id) DO NOTHING;
