INSERT INTO diagnosticos (id, user_id, user_name, user_email, cultivo, cultivo_nombre, con_foto, consulta_texto, clima_contexto, resultado, confirmado_por_usuario, fecha, mes) VALUES ('xSv7DfdP7WaxkDzLr2fS', 'yhC9xTlB6yPlERoUgg2dh2WNsxq1', 'Carlos Pérez Dávila', 'visionario2306@gmail.com', 'cana', 'Caña de azúcar', true, NULL, NULL, '{"tiene_problema":true,"productos":[{"frecuencia":"Una aplicación post-emergencia temprana de las malezas y la caña (2-3 hojas).","ingrediente_activo":"Ametrina + Atrazina","nombre":"Gesapax Combi","carencia":"No aplica para cosecha de caña.","dosis":"3.0 - 4.0 kg/ha"},{"frecuencia":"Una aplicación pre-emergencia o post-emergencia temprana de malezas.","carencia":"No aplica para cosecha de caña.","ingrediente_activo":"Diuron","nombre":"Diuron 80 WG","dosis":"1.5 - 2.5 kg/ha"}],"que_tiene":"Detección: Se observa una alta densidad de malezas de diferentes tipos (gramíneas y algunas de hoja ancha) creciendo entre las hileras de la caña de azúcar y compitiendo por recursos. Signos: Reducción del vigor de la caña, posible amarillamiento leve en algunas plantas por competencia. Causas probables: Falta de control oportuno de malezas, condiciones favorables para su crecimiento (humedad, luz). Prevención: Preparación adecuada del terreno, uso de variedades de caña vigorosas, rotación de cultivos, control temprano de malezas.","gravedad":"moderada","nombre_problema":"Malezas gramíneas y de hoja ancha","nombre_cientifico":"Varias especies"}'::jsonb, NULL, '2026-07-28T01:10:51.016Z', 7) ON CONFLICT (id) DO NOTHING;
