INSERT INTO registros_parcela (id, parcela_id, user_id, foto, recomendacion, dias_desde_siembra, fecha) VALUES ('q1RFsrDKcMySTN0FbZ0u', 'fjnaeKtRfrGPxHWpEgp4', '9GdcjYjtvaW2YjiE6bdvwvRxmJV2', 'data:image/jpeg;base64,...', '¡Claro! Analizando la imagen de la hoja de papa de la variedad Yungay, a los 107 días de siembra en Cutervo, Cajamarca, observo una **clorosis generalizada y amarillamiento en las hojas más viejas**, lo que sugiere una posible deficiencia nutricional, probablemente de nitrógeno o magnesio, o incluso un estrés hídrico.
INSERT INTO historial_clinico (id, user_id, parcela_id, parcela_nombre, cultivo, tiene_problema, problema, gravedad, recomendacion, fuente) VALUES ('5Q3y6GtyVyjMR0mshzWZ', 'GsCQ2RXNkzLOWPxNLQKNxDWBVYy2', NULL, 'Cutervo, Cutervo', 'maiz', true, 'Gusano Cogollero', 'moderada', 'Monitorear constantemente el cultivo para detectar nuevas infestaciones. Realizar control cultural como la eliminación manual de larvas en infestaciones bajas. Mantener el campo limpio de malezas que puedan servir de refugio a la plaga. Si la infestación es alta, se recomienda el uso de insecticidas.', 'diagnostico') ON CONFLICT (id) DO NOTHING;
INSERT INTO historial_clinico (id, user_id, parcela_id, parcela_nombre, cultivo, tiene_problema, problema, gravedad, recomendacion, fuente) VALUES ('9pYHxPgeO7uU1k7PEH0k', 'yhC9xTlB6yPlERoUgg2dh2WNsxq1', NULL, 'Pomalca, Pomalca', 'cana', true, 'Malezas', 'moderada', 'Primero, puedes hacer un control manual o mecánico si las malezas no son muchas y la caña está pequeña. Si ya están grandes o son muchas, lo mejor es usar un herbicida. También es importante mantener los bordes de la parcela limpios para evitar que las malezas se propaguen.', 'diagnostico') ON CONFLICT (id) DO NOTHING;
INSERT INTO historial_clinico (id, user_id, parcela_id, parcela_nombre, cultivo, tiene_problema, problema, gravedad, recomendacion, fuente) VALUES ('YyV9YEphSHzEWZs4Vanf', 'GsCQ2RXNkzLOWPxNLQKNxDWBVYy2', NULL, 'Cutervo, Cutervo', 'maiz', true, 'Gusano Cogollero', 'moderada', 'Primero, revisa tus plantas para confirmar la presencia de las larvas. Si encuentras muchas, es hora de aplicar un insecticida. También puedes hacer un control cultural: eliminar las malezas alrededor del cultivo, ya que pueden ser refugio para la plaga. Si el ataque es leve, puedes retirar las larvas a mano. Para ataques moderados como este, necesitamos una solución química.', 'diagnostico') ON CONFLICT (id) DO NOTHING;
INSERT INTO historial_clinico (id, user_id, parcela_id, parcela_nombre, cultivo, tiene_problema, problema, gravedad, recomendacion, fuente) VALUES ('d39QRx7faYRjWoqSWWSU', 'wzO7nbiJNKVdNUH7kBmRY3UNSE43', NULL, 'cajamarca', 'papa', true, 'Indicios de Tizón Tardío o Alternaria', 'moderada', '1. **Inspección detallada:** Buscar patrones de las manchas (circulares con anillos concéntricos para Alternaria, o irregulares y acuosas para Phytophthora). Verificar la presencia de esporangios en el envés de las hojas (blanco algodonoso para Phytophthora). 2. **Manejo cultural:** Eliminar y destruir las plantas severamente afectadas. Mejorar la ventilación entre plantas si es posible. 3. **Aplicación de fungicida:** Una vez identificada la enfermedad, aplicar el fungicida adecuado.', 'diagnostico') ON CONFLICT (id) DO NOTHING;
