INSERT INTO conversaciones_voz (id, user_id, mensajes) VALUES ('7s5CeZE05R6sqnL2YGV8', 'GsCQ2RXNkzLOWPxNLQKNxDWBVYy2', '[{"role":"assistant","content":"¡Hola! Soy tu asistente agrícola. Puedo darte información del clima de tu zona, recomendaciones para tus cultivos, o consultar el pronóstico del SENAMHI. ¿En qué te puedo ayudar?"},{"role":"user","content":"Quiero saber la temperatura la humedad de mi zona Y si va a llover o no va a llover"},{"role":"assistant","content":"¡Hola, José Edin! Con gusto te doy la información del clima para tu zona en Cutervo. 🚜\n\nAhorita mismo, la temperatura está en unos frescos 13.5°C y la humedad en un 89%. 💧 El SENAMHI pronostica que hoy la temperatura oscilará entre 11.6°C y 17.9°C, y sí, ¡hay un 71% de probabilidad de lluvia, con unos 7mm esperados! 🌧️\n\nAsí que, amigo, ¡prepara el paraguas y protege tus cultivos! 😉"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO conversaciones_voz (id, user_id, mensajes) VALUES ('QaTwAOP8b0I0mRRjeInz', 'yhC9xTlB6yPlERoUgg2dh2WNsxq1', '[{"role":"assistant","content":"¡Hola! Soy tu asistente agrícola. Puedo darte información del clima de tu zona, recomendaciones para tus cultivos, o consultar el pronóstico del SENAMHI. ¿En qué te puedo ayudar?"},{"role":"user","content":"Dame la temperatura actual la velocidad del viento actual la unidad relativa actual y el pronóstico del tiempo"},{"role":"assistant","content":"¡Hola, Carlos! Gusto en saludarte. 🧑‍🌾\n\nAquí te tengo los datos del clima en Pampagrande:\n\n*   **Temperatura actual:** 20.8°C\n*   **Velocidad del viento:** 11.9 km/h\n*   **Humedad relativa:** 88%\n*   **Pronóstico para hoy:** La temperatura irá de 20.8°C a 28.2°C, con solo un 2% de probabilidad de lluvia.\n\n¡Cualquier otra consulta, aquí estoy para ayudarte!"},{"role":"user","content":"Dame la temperatura actual la velocidad de viento actual la humedad relativa actual y el pronóstico del tiempo"},{"role":"assistant","content":"¡Claro que sí, Carlos! Con gusto te doy la información actualizada:\n\n*   **Temperatura actual:** 20.8°C\n*   **Velocidad del viento:** 11.9 km/h\n*   **Humedad relativa:** 88%\n*   **Pronóstico para hoy:** Se espera un rango de temperatura entre 20.8°C y 28.2°C, con una probabilidad de lluvia bajita, solo del 2%.\n\n¡Cualquier otra duda, no dudes en consultarme!"},{"role":"user","content":"dame los datos del clima para pumalca"},{"role":"assistant","content":"¡Hola de nuevo, Carlos! Te doy los datos del clima para Pomalca, que es la estación más cercana a tu ubicación:\n\n*   **Temperatura actual:** 20.8°C\n*   **Velocidad del viento:** 11.9 km/h\n*   **Humedad relativa:** 88%\n*   **Pronóstico para hoy:** La temperatura irá de 20.8°C a 28.2°C, con solo un 2% de probabilidad de lluvia.\n\n¡Ya sabes, si necesitas algo más, me avisas! 🇵🇪"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
